import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.Cc-oPviL.js";const g=JSON.parse('{"title":"00 · 数据库导读：数据怎么存下来还不乱","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/db/00.md","filePath":"bagu/db/00.md"}'),l={name:"bagu/db/00.md"};function i(e,s,p,r,u,d){return a(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="_00-·-数据库导读-数据怎么存下来还不乱" tabindex="-1">00 · 数据库导读：数据怎么存下来还不乱 <a class="header-anchor" href="#_00-·-数据库导读-数据怎么存下来还不乱" aria-label="Permalink to &quot;00 · 数据库导读：数据怎么存下来还不乱&quot;">​</a></h1><blockquote><p>数据库这块是&quot;四个模块的交汇点&quot;：索引用到数据结构，事务用到操作系统的日志和刷盘，并发用到锁，查询用到网络往返。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>数据库要同时解决四个问题：<strong>存得下（存储）、找得快（索引）、不出错（事务）、扛得住并发（锁/MVCC）</strong>。</p><h2 id="生活类比-图书馆" tabindex="-1">生活类比：图书馆 <a class="header-anchor" href="#生活类比-图书馆" aria-label="Permalink to &quot;生活类比：图书馆&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据库</th><th>图书馆</th></tr></thead><tbody><tr><td>表</td><td>一个书架</td></tr><tr><td>行</td><td>一本书</td></tr><tr><td>索引</td><td>索引柜里的卡片（另存一份，按序排好）</td></tr><tr><td>聚簇索引</td><td>书按编号顺序摆在架上（书本身就是目录）</td></tr><tr><td>非聚簇索引</td><td>单独的卡片柜，卡片上写着&quot;书在几排几号&quot;</td></tr><tr><td>事务</td><td>一次借还流程：要么全部办完，要么都不算</td></tr><tr><td>redo log</td><td>操作日志：先记&quot;我做了什么&quot;，万一出事能重做</td></tr><tr><td>undo log</td><td>备份：万一要撤销，能还原旧值</td></tr><tr><td>锁</td><td>借出登记本：我借走了别人不能拿</td></tr><tr><td>MVCC</td><td>同一本书存了多个版本的副本，各看各的，互不干扰</td></tr><tr><td>隔离级别</td><td>允许你看到别人&quot;改到一半&quot;的书吗</td></tr></tbody></table><h2 id="模块地图-5-篇怎么接" tabindex="-1">模块地图：5 篇怎么接 <a class="header-anchor" href="#模块地图-5-篇怎么接" aria-label="Permalink to &quot;模块地图：5 篇怎么接&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-- 01 索引：怎么找得快</span></span>
<span class="line"><span>|      &lt;- 依赖：B+ 树（数据结构 03-03）</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- 02 事务：怎么保证不出错</span></span>
<span class="line"><span>|      &lt;- 依赖：日志、刷盘（操作系统 IO）</span></span>
<span class="line"><span>|      ACID 里的 C 和 I，靠 03 和 04 实现</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- 03 MVCC：用&quot;多版本&quot;减少锁（乐观思路）</span></span>
<span class="line"><span>+-- 04 锁与死锁：用&quot;锁&quot;保证互斥（悲观思路）</span></span>
<span class="line"><span>|      两者是解决同一问题的两条路</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- 05 SQL 执行与优化：怎么把上面都用对</span></span></code></pre></div><p><strong>关键理解</strong>：<strong>03（MVCC）和 04（锁）是解决同一问题的两条路</strong>。</p><ul><li><strong>锁</strong>：悲观。我怕你改，先锁住，你等着。</li><li><strong>MVCC</strong>：乐观。我不锁你，我给你看旧版本，你随便读。</li></ul><p>MySQL 的 InnoDB 是<strong>两者混用</strong>：读用 MVCC（不加锁），写用锁。这就是为什么&quot;读不阻塞写，写不阻塞读&quot;。</p><h2 id="一条主线-一条-sql-是怎么执行的" tabindex="-1">一条主线：一条 SQL 是怎么执行的 <a class="header-anchor" href="#一条主线-一条-sql-是怎么执行的" aria-label="Permalink to &quot;一条主线：一条 SQL 是怎么执行的&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 客户端发 SQL &gt; 网络传到服务端（网络篇）</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>② 连接器：验证账号密码、权限</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>③ 查询缓存（MySQL 8.0 已移除，因为命中率太低）</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>④ 解析器：词法分析、语法分析，生成语法树</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>⑤ 优化器：选索引、决定 join 顺序，生成执行计划</span></span>
<span class="line"><span>   v  &lt; 这一步决定了 SQL 快不快，EXPLAIN 看的就是它</span></span>
<span class="line"><span>⑥ 执行器：按执行计划调用存储引擎接口</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>⑦ 存储引擎（InnoDB）：</span></span>
<span class="line"><span>   a. 从 Buffer Pool 找页（内存里的缓存）</span></span>
<span class="line"><span>   b. 找不到 &gt; 从磁盘读一页（16KB）到 Buffer Pool（一次 IO）</span></span>
<span class="line"><span>   c. 在页里用 B+ 树定位到行</span></span>
<span class="line"><span>   d. 读操作：用 MVCC 判断这个版本你可见吗</span></span>
<span class="line"><span>   e. 写操作：加锁 &gt; 改 Buffer Pool &gt; 写 undo log &gt; 写 redo log（prepare）&gt; 写 binlog &gt; redo log（commit）</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>⑧ 返回结果</span></span></code></pre></div><p><strong>这条线把四个模块全串起来了</strong>：</p><ul><li>① 是网络</li><li>⑦a/b 是操作系统（虚拟内存、页缓存、IO 模型）</li><li>⑦c 是数据结构（B+ 树）</li><li>⑦d/e 是事务、MVCC、锁</li></ul><h2 id="学这个模块的方法" tabindex="-1">学这个模块的方法 <a class="header-anchor" href="#学这个模块的方法" aria-label="Permalink to &quot;学这个模块的方法&quot;">​</a></h2><ol><li><strong>所有&quot;为什么&quot;都要落到&quot;磁盘很慢&quot;这个前提上</strong>。数据库的绝大多数设计（B+ 树、Buffer Pool、日志、批量刷盘）都是在对抗磁盘的慢。</li><li><strong>一定要跑 EXPLAIN</strong>。看不懂执行计划，索引那篇等于没学。</li><li><strong>画版本链</strong>。MVCC 是最抽象的一篇，必须画出&quot;一行数据的多个版本 + ReadView 怎么判断可见性&quot;。</li><li><strong>别背隔离级别的定义，背&quot;每个级别解决了哪个异常&quot;</strong>。</li></ol><h2 id="和其他模块的连接" tabindex="-1">和其他模块的连接 <a class="header-anchor" href="#和其他模块的连接" aria-label="Permalink to &quot;和其他模块的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/dsa/03">树与堆</a>：B+ 树是索引的基础，树高 = 磁盘 IO 次数</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/04">IO 模型与零拷贝：等设备的时候，CPU 在干什么</a>：Buffer Pool 是&quot;用内存缓存磁盘页&quot;，本质是 IO 优化</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/02">虚拟内存：让每个程序都以为自己独占一台机器</a>：Buffer Pool 的淘汰用 LRU 变种（改良 LRU），和页面置换同源</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/03">调度与并发同步：CPU 分给谁，共享数据谁先动</a>：事务隔离靠锁，锁理论和 OS 完全一致</li><li><strong>&gt; 影响</strong> 工程实践：分库分表、读写分离、缓存一致性、分布式事务</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：数据库和文件系统到底差在哪？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>文件系统只负责&quot;存&quot;，数据库在&quot;存&quot;之上加了四层能力：</p><ol><li><strong>结构化查询</strong>：文件系统只能按路径找；数据库能&quot;找出所有 age &gt; 20 且 city = 北京 的记录&quot;，靠索引加速。</li><li><strong>并发控制</strong>：多个进程同时写同一个文件会互相覆盖；数据库用锁和 MVCC 保证正确。</li><li><strong>事务</strong>：文件写到一半断电就坏了；数据库能保证&quot;要么全成，要么全不成&quot;。</li><li><strong>约束与一致性</strong>：主键唯一、外键、非空——文件系统不管这些。</li></ol><p><strong>一句话</strong>：文件系统是&quot;字节的容器&quot;，数据库是&quot;<strong>有语义、可并发、可回滚</strong>的字节容器&quot;。</p></details><p><strong>Q2：为什么数据库要自己管理缓存（Buffer Pool），不用操作系统的页缓存？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>三个原因：</p><ol><li><strong>可控的淘汰策略</strong>。OS 的页缓存用 LRU，但它不知道&quot;哪些页是热数据&quot;。数据库知道自己的访问模式，可以用改良 LRU（比如 InnoDB 的&quot;分区 LRU&quot;，防止全表扫描把热数据冲掉）。</li><li><strong>需要预读和批量</strong>。数据库知道&quot;读了索引页，大概率要读数据页&quot;，可以主动预读。</li><li><strong>避免双重缓存</strong>。如果既走 OS 页缓存又走 Buffer Pool，同一份数据在内存里存两份，浪费。所以 InnoDB 通常用 <code>O_DIRECT</code> 绕过 OS 缓存。</li></ol><p><strong>代价</strong>：数据库要自己实现缓存淘汰、刷脏页、崩溃恢复——复杂度大幅上升。但对性能敏感的场景，这个代价是值得的。</p></details><p><strong>Q3：为什么 MySQL 8.0 移除了查询缓存？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>命中率太低，维护成本太高</strong>。</p><p>查询缓存要求&quot;SQL 文本完全一致&quot;才命中——多一个空格、大小写不同、参数不同，都不命中。</p><p>更致命的是：<strong>任何对表的写操作，都会让这张表的所有查询缓存失效</strong>。在写多的场景下，缓存刚建好就被清空，几乎全是无效功。</p><p>而且每次检查缓存都要加全局锁，反而成为性能瓶颈。</p><p><strong>替代方案</strong>：应用层缓存（Redis）+ InnoDB 的 Buffer Pool（缓存数据页而不是查询结果）。后者粒度更细，写操作只需要让相关的页失效。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;图书馆&quot;类比会让人以为索引和数据是分开的两份</strong>。实际上聚簇索引的叶子节点<strong>就是数据本身</strong>，没有&quot;卡片柜&quot;。</li><li><strong>&quot;事务&quot;不是&quot;锁&quot;</strong>。事务是&quot;一组操作的原子性保证&quot;，锁只是实现隔离的一种手段（MVCC 就不用锁）。</li><li><strong>数据库的&quot;行&quot;不是&quot;一整块连续存储&quot;</strong>。行存在页里，页之间可以不连续，靠 B+ 树组织。</li><li><strong>不要以为&quot;加了索引就一定快&quot;</strong>。索引有维护成本（每次写要更新索引），且区分度低时（比如性别字段）几乎没用。</li><li><strong>&quot;ACID&quot;里的 C（一致性）不是数据库实现的</strong>，它是<strong>应用和数据库共同保证的目标</strong>。A、I、D 是手段，C 是结果。这个区分很多人答错。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能说出数据库要解决的四个核心问题（存、找、不错、并发）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能画出 5 篇的依赖图，并说出&quot;MVCC 和锁是同一问题的两条路&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能完整讲出&quot;一条 SQL 的执行流程&quot;（至少 6 个步骤）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能说出 Buffer Pool 存在的理由，以及它为什么不用 OS 页缓存</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能解释&quot;数据库和文件系统的本质区别&quot;（要说出 4 点）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能说清&quot;ACID 里 C 不是数据库实现的&quot;这句话的含义</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,30)])])}const h=t(l,[["render",i]]);export{g as __pageData,h as default};
